KIND_CYCLE = ["definition", "identity", "classification", "composition", "relationship", "state", "lifecycle", "temporal", "spatial", "provenance", "ownership", "authority", "requirement", "constraint", "process", "event", "measurement", "evidence", "quality", "validation", "security", "privacy", "retention", "access", "exception", "interoperability", "decision"]


def build_finding(raw, ordinal):
    finding_id, name, description, primary_kind, refs, value_kind, required = raw
    kinds = [primary_kind, KIND_CYCLE[(ordinal * 5 + 4) % len(KIND_CYCLE)], KIND_CYCLE[(ordinal * 11 + 8) % len(KIND_CYCLE)]]
    for position in range(1, 3):
        while kinds[position] in kinds[:position]:
            kinds[position] = KIND_CYCLE[(KIND_CYCLE.index(kinds[position]) + 1) % len(KIND_CYCLE)]
    subject = name.lower()
    questions = [
        {"id": f"{finding_id}-q01", "text": f"What process-scoped identities, classifications, criteria, roles, versions, values and explicit unknowns establish {subject}?", "kind": kinds[0], "answer_data": ["identifiers and classifications", "criteria, roles and scope", "versions, values and explicit unknowns"]},
        {"id": f"{finding_id}-q02", "text": f"Which authority, source, method, evidence, event time, knowledge time, confidence and limitations support {subject}?", "kind": kinds[1], "answer_data": ["authority and source", "method and evidence", "event and knowledge time", "confidence, contradiction and limitations"]},
        {"id": f"{finding_id}-q03", "text": f"How may {subject} be validated, accessed, challenged, corrected, related, retained or disposed without losing prior recruitment history?", "kind": kinds[2], "answer_data": ["validation and access rules", "challenge and authorized correction", "relations and lineage", "retention, hold and disposition"]},
    ]
    return {"id": finding_id, "name": name, "description": description, "source_refs": refs, "questions": questions, "data_elements": [{"id": f"{finding_id}-data", "name": f"{name} data", "description": f"Structured recruitment-process data for {subject} with scope, provenance, time, confidence and access marking.", "value_kind": value_kind, "cardinality": "1" if required else "0..n", "required": required, "source_refs": refs}], "artifacts": [{"id": f"{finding_id}-record", "name": f"{name} record", "description": f"Versioned evidence-bearing recruitment-process record for {subject} with authority, time, provenance and access marking.", "media_or_form": ["logical recruitment assertion", "plan, reference, event, evidence, decision, outcome or governance record"], "serial": True, "identity_strategy": f"Recruitment process identifier plus {finding_id} assertion, artifact or event identifier; title, candidate name, date, timestamp and digest never identify the process alone.", "source_refs": refs}], "inline_only_rationale": None}


def build_structure():
    bundles = []
    ordinal = 0
    for bundle_id, name, description, rationale, refs, layer_rows in STRUCTURE:
        layers = []
        for layer_id, layer_name, layer_description, layer_refs, finding_rows in layer_rows:
            findings = []
            for raw in finding_rows:
                ordinal += 1
                findings.append(build_finding(raw, ordinal))
            layers.append({"id": layer_id, "name": layer_name, "description": layer_description, "source_refs": layer_refs, "findings": findings})
        bundles.append({"id": bundle_id, "name": name, "description": description, "rationale": rationale, "source_refs": refs, "layers": layers})
    return {"bundles": bundles}


